    nearest = [0.0 for x in sites]
    outer = [0.0 for x in sites]
    second = [6.0 for x in sites]
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0:
            if occ[i] > 0.0 and occ[j] > 0.0:
                if nearest[i] == 0.0 or d < nearest[i]:
                    nearest[i] = d
    for bond in bonds:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d <= 6.0:
            if occ[i] > 0.0 and occ[j] > 0.0 and nearest[i] > 0.0:
                if d <= 1.25 * nearest[i]:
                    outer[i] = max(outer[i], d)
                else:
                    second[i] = min(second[i], d)
    total = 0.0
    weight = 0.0
    for i in range(n):
        if occ[i] > 0.0 and outer[i] > 0.0:
            total += occ[i] * log(max(1.0, second[i] / outer[i]))
            weight += occ[i]
    return total / max(weight, 1e-12)

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, x.get('occupancy', 1.0) or 0.0) for x in sites]
    chi = [0.0 for x in sites]
    inverse = [0.0 for x in sites]
    charge = [0.0 for x in sites]
    numerator = 0.0
    denominator = 0.0
    for i in range(n):
        p = props.get(sites[i].get('element')) or {}
        ion = p.get('first_ionization_energy_eV')
        affinity = p.get('electron_affinity_eV')
        if ion is not None and affinity is not None and occ[i] > 0.0:
            if isfinite(ion) and isfinite(affinity):
                chi[i] = 0.5 * (ion + affinity)
                inverse[i] = 1.0 / max(0.5, ion - affinity)
                numerator += occ[i] * chi[i] * inverse[i]
                denominator += occ[i] * inverse[i]
    if denominator <= 0.0:
        return 0.0
    chemical_potential = numerator / denominator
    for i in range(n):
        charge[i] = (chemical_potential - chi[i]) * inverse[i]
    total = 0.0
    for bond in s.get('neighbors') or []:
        i = bond.get('i', -1)
        j = bond.get('j', -1)
        d = bond.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 0.0 < d < 6.0:
            kernel = 1.0 / max(d, 0.1) - 1.0 / 6.0
            total += occ[i] * occ[j] * charge[i] * charge[j] * kernel
    return 7.199822739 * total / max(sum(occ), 1e-12)
